def tuple_division(dividend, divisor):

    """This exercise requires you to divide a tuple by another tuple element-wise"""

### Solution:


    try:
        # Check if the inputs are tuples
        if not isinstance(dividend, tuple) or not isinstance(divisor, tuple):
