def find_common_prefix(names):

    """
    Given a list of names, find the longest common prefix among them.

    Args:
    names (list): A list of strings representing names.

    Returns:
    str: The longest common prefix among the names.
    """

### Solution:


    common_prefix = ""
    i = 0

    while True:
        try:
            common_char = names[0][i]
        except IndexError:
            break

        for name in names:
            try:
                if name[i] != common_char:
                    return common_prefix
            except IndexError:
                return common_prefix

        common_prefix += common_char
        i += 1

    return common_prefix

