    """Given a dictionary of Athlete's career statistics, concatenate the scores of all games played, 
    using nested try-except statements to handle any possible KeyError or TypeError exceptions that may occur."""

### Solution:


    total_scores = []

    try:
        for season in career_stats.values():
            try:
                for game_stats in season:
                    try:
                        total_scores.append(game_stats['score'])
                    except (KeyError, TypeError):
                        continue
            except (KeyError, TypeError):
                continue
    except (KeyError, TypeError):
        return "Invalid career statistics input."

    return total_scores

