def find_root(x, n):

    """This function calculates the nth root of a number x"""

### Solution:


    try:
        if x < 0:
            raise ValueError("x must be a positive number")
        elif n <= 0:
            raise ValueError("n must be a positive integer")

        guess = 1.0
        epsilon = 0.01
        num_guesses = 0

        while True:
            try:
                if abs(guess**n - x) <= epsilon:
                    return guess
                else:
                    guess = guess - (((guess**n) - x) / (n * (guess**(n-1))))
                    num_guesses += 1
                    if num_guesses > 50:
                        raise RuntimeError("Failed to find root within required precision")
            except ZeroDivisionError:
                print("n = 0 not allowed")
                break

    except ValueError as ve:
        print(ve)

