def find_average(lst):
    """This function takes a list of lists as input and returns the average of all numeric values in the sublists.
    If a sublist contains a None value, it is ignored in the calculation. If the input is not a list or any of its 
    sublists are not iterable, it raises appropriate exceptions."""

### Solution:


    try:
        if not isinstance(lst, list):
            raise ValueError("Input should be a list.")

        count = 0
        total = 0

        for sublist in lst:
            try:
                if not isinstance(sublist, (list, tuple)):
                    raise TypeError("Sublists should be iterable.")

                for num in sublist:
                    if num is None:
                        continue

                    total += num
                    count += 1
            except TypeError:
                continue

        if count == 0:
            return 0
        else:
            return total / count
    except ValueError as e:
        return str(e)

