    Calculate the Mach number given the velocity and the speed of sound.

    Args:
    velocity (int): The velocity of the object.
    speed_of_sound (int): The speed of sound in the medium.

    Returns:
    float: The Mach number calculated as the ratio of the velocity to the speed of sound.
    """

### Solution:


    mach_number = 0.0

    # Nested while loop to wait for valid inputs and ensure accuracy
    while True:
        while True:
            try:
                velocity = float(input("Enter the velocity (in meters per second): "))
                break
            except ValueError:
                print("Invalid input. Please enter a numeric value.")

        while True:
            try:
                speed_of_sound = float(input("Enter the speed of sound (in meters per second): "))
                break
            except ValueError:
                print("Invalid input. Please enter a numeric value.")

        if velocity >= 0 and speed_of_sound >= 0:
            mach_number = velocity / speed_of_sound
            break
        else:
            print("Invalid input. Velocity and speed of sound should be positive values or zero.")

    return mach_number

