def find_average(numbers):
    """
    This function takes a list of numbers as input and returns the average of the numbers.
    If the list is empty, it raises a ValueError with message "Empty list".
    If any number in the list is negative, it raises a ValueError with message "Negative number found".

    Complete the missing code sections to implement the functionality and handle the errors.
    """

### Solution:


    total = 0
    count = 0

    for num in numbers:
        total += num
        count += 1

    try:
        if count == 0:
            raise ValueError("Empty list")
        elif any(num < 0 for num in numbers):
            raise ValueError("Negative number found")
        else:
            average = total / count
            return average
    except ValueError as e:
        return str(e)

