def find_common_elements(set1, set2):

    """
    Given two sets, find the common elements between them.

    Args:
    set1 - a set containing elements
    set2 - a set containing elements

    Returns:
    A list of common elements between set1 and set2.
    """

### Solution:


    try:
        common_elements = list(set1.intersection(set2))
    except AttributeError:
        common_elements = []
        nested_exception = None

        try:
            set1.intersection()
        except AttributeError as e:
            nested_exception = e

        try:
            set2.intersection()
        except AttributeError as e:
            if e == nested_exception:
                common_elements = []
            else:
                raise Exception("Exception handling failed!")

    return common_elements

