def calculate_crop_yield(temperature, rainfall):
    """Calculates the crop yield based on temperature and rainfall.
    Returns the crop yield in tons per acre.

    Args:
    temperature (float): The temperature in degrees Celsius.
    rainfall (float): The rainfall in millimeters.

    Returns:
    float: The crop yield in tons per acre.
    """

### Solution:


    try:
        temperature = float(temperature)
        rainfall = float(rainfall)
    except ValueError:
        return "Invalid input. Temperature and rainfall must be floating-point numbers."

    try:
        if temperature < 0:
            raise ValueError("Temperature cannot be below 0 degrees Celsius.")
        if rainfall < 0:
            raise ValueError("Rainfall cannot be negative.")

        if temperature < 10:
            return 0

        if rainfall < 100:
            return 0

        if temperature > 40:
            return 0

        if rainfall > 1000:
            return 0

        crop_yield = 10 * (temperature - 10) * (rainfall - 100)
        return crop_yield

    except ValueError as e:
        return str(e)

