def concatenate_strings(list1, list2):
    """
    This function takes two lists of strings as input and concatenates them using nested try-except statements.

    Args:
    list1 (list): The first list of strings.
    list2 (list): The second list of strings.

    Returns:
    str: The concatenated string.

    Raises:
    ValueError: If an element in list1 or list2 is not a string.
    IndexError: If the indexes to access elements in list1 or list2 are out of range.
    """

### Solution:


    try:
        result = ""
        for i in range(len(list1)):
            try:
                if i >= len(list2):
                    raise IndexError("Index out of range: list2")
                if not isinstance(list1[i], str) or not isinstance(list2[i], str):
                    raise ValueError("Invalid element type: must be string")
                result += list1[i] + list2[i]
            except IndexError:
                result += list1[i]
            except ValueError:
                pass
    except IndexError:
        result = ""
    except ValueError:
        result = ""

    return result

